// intent: Exercise general comparison operators on same-type scalar values through mixed comparison paths.
#include <nlohmann/json.hpp>
#include <iostream>
int main() {
    try {
        nlohmann::json a = 5;
        nlohmann::json b = 10;
        bool eq = (a == b);
        bool lt = (a < b);
        std::cout << std::boolalpha << "eq: " << eq << ", lt: " << lt << "\n";
    } catch (const std::exception& e) {
        std::cout << "Exception: " << e.what() << "\n";
    }
    return 0;
}
